function HabitModal({ habit, save, remove, close }) { const [form, setForm] = useState({ name: habit.name || "", target: habit.target || 1, unit: habit.unit || "veces" }); const update = (key, value) => setForm({ ...form, [key]: value }); const values = habit.history || []; const metric = habit.unit || "veces"; const points = values.map((value, index) => `${index * 50},${110 - value}`).join(" "); return <Modal title={habit.id ? "Editar hábito" : "Nuevo hábito"} close={close}>{habit.id && values.length > 0 && <><p className="mt-2 text-sm text-zinc-500">Cumplimiento de los últimos 7 días</p><svg viewBox="0 0 300 130" className="mt-4 h-40 w-full" role="img" aria-label={`Tracker de ${habit.name}`}><text x="5" y="9" className="fill-zinc-400 text-[7px]">día / {metric}</text><path d="M0 10V110H300M0 60H300" fill="none" stroke="currentColor" strokeOpacity=".15" strokeDasharray="3 4" /><polyline points={points} fill="none" stroke="#84cc16" strokeWidth="4" strokeLinecap="round" strokeLinejoin="round" />{values.map((value, index) => { const previous = values[index - 1]; const trend = index === 0 ? "Punto inicial" : value > previous ? "Mejoraste" : value < previous ? "Empeoraste" : "Sin cambios"; return <circle key={index} cx={index * 50} cy={110 - value} r="4" fill="#84cc16"><title>Día {index + 1}: {value}% · {trend}</title></circle>; })}</svg></>}<div className="mt-5 space-y-3"><label className="text-xs text-zinc-500">Nombre del hábito<input autoFocus value={form.name} onChange={(event) => update("name", event.target.value)} className={`${inputClass} mt-1`} /></label><div className="grid grid-cols-2 gap-3"><label className="text-xs text-zinc-500">Meta por día<input type="number" min="1" value={form.target} onChange={(event) => update("target", event.target.value)} className={`${inputClass} mt-1`} /></label><label className="text-xs text-zinc-500">Unidad<input value={form.unit} onChange={(event) => update("unit", event.target.value)} placeholder="vasos, veces, páginas..." className={`${inputClass} mt-1`} /></label></div></div><div className="mt-6 flex gap-2">{habit.id && <button onClick={() => remove(habit.id)} className="rounded-xl border border-red-200 px-4 py-3 text-sm text-red-600">Eliminar</button>}<button onClick={() => form.name.trim() && save({ id: habit.id || Date.now(), name: form.name.trim(), target: Math.max(1, Number(form.target) || 1), unit: form.unit.trim() || "veces", count: habit.count || 0, progress: habit.progress || 0, history: habit.history || [] })} className="flex-1 rounded-xl bg-zinc-900 py-3 text-sm font-semibold text-white">Guardar</button></div></Modal>; }

function TaskList({ tasks, date, setDate, toggle, openTask }) { const visible = tasks.filter((task) => task.date === date).sort((a, b) => a.time.localeCompare(b.time)); return <Card><CardHeader eyebrow={`Agenda del ${date}`} title="Tareas" action={<button onClick={() => openTask(null, date)} className="flex items-center gap-1 text-sm font-semibold text-lime-700"><Plus size={16} /> Añadir</button>} /><DatePicker value={date} onChange={setDate} className="mb-5" /><div className="space-y-1">{visible.length ? visible.map((task) => <button key={task.id} onClick={() => toggle(task.id)} onDoubleClick={() => openTask(task, date)} className="flex w-full items-center gap-3 rounded-xl p-3 text-left transition-colors hover:bg-zinc-50 dark:hover:bg-zinc-800"><span className={`grid h-5 w-5 shrink-0 place-items-center rounded-full border transition-transform duration-300 ${task.done ? "scale-95 border-lime-500 bg-lime-400 text-lime-950" : "border-zinc-300"}`}>{task.done && <Check size={13} />}</span><span className="w-12 text-xs text-zinc-400">{task.time}</span><span className={`flex-1 text-sm font-medium transition-[color] duration-500 ${task.done ? "text-zinc-400" : "dark:text-zinc-100"}`}><span className={task.done ? "task-strike" : ""}>{task.title}</span></span><span className="rounded-full bg-zinc-100 px-2 py-1 text-[10px] text-zinc-500">{task.category} · {task.priority}</span></button>) : <p className="py-8 text-center text-sm text-zinc-400">No hay tareas para este día.</p>}</div></Card>; }

function EventList({ events, date, openEvent }) { const visible = events.filter((event) => event.date === date).sort((a, b) => a.time.localeCompare(b.time)); return <Card><CardHeader eyebrow={`Eventos del ${date}`} title="Eventos" action={<button onClick={() => openEvent(null, date)} className="flex items-center gap-1 text-sm font-semibold text-lime-700"><Plus size={16} /> Añadir</button>} />{visible.length ? <div className="space-y-2">{visible.map((event) => <div key={event.id} onDoubleClick={() => openEvent(event, date)} className="flex cursor-pointer items-center gap-3 rounded-xl p-3" style={{ backgroundColor: `${event.color}55` }}><span className="h-8 w-1 rounded-full" style={{ backgroundColor: event.color }} /><span className="text-xs text-zinc-500">{event.time}</span><div className="flex-1"><p className="text-sm font-medium">{event.title}</p><p className="text-xs text-zinc-500">{event.type}</p></div></div>)}</div> : <p className="py-6 text-center text-sm text-zinc-400">No hay eventos para este día.</p>}</Card>; }

function currentStreak(habit) { let streak = 0; for (let index = habit.history.length - 1; index >= 0; index--) { if (habit.history[index] >= 100) streak++; else break; } return streak; }

function Habits({ habits, onToggle, openHabit }) { const clickTimer = useRef(null); return <Card><CardHeader eyebrow="Rituales diarios" title="Hábitos saludables" action={<button onClick={() => openHabit({ name: "", target: 1, unit: "veces" })} className="flex items-center gap-1 text-sm font-semibold text-lime-700"><Plus size={16} /> Nuevo</button>} /><div className="space-y-5">{habits.map((habit) => { const streak = currentStreak(habit); return <button key={habit.id} onClick={(event) => { if (event.detail === 2) { clearTimeout(clickTimer.current); openHabit(habit); } else { clickTimer.current = window.setTimeout(() => onToggle(habit.id), 250); } }} className="flex w-full items-center gap-3 rounded-xl p-2 text-left hover:bg-zinc-50 dark:hover:bg-zinc-800"><span className={`grid h-5 w-5 shrink-0 place-items-center rounded-md border transition-transform duration-300 active:scale-75 ${habit.progress >= 100 ? "border-lime-500 bg-lime-400" : "border-zinc-300"}`}>{habit.progress >= 100 && <Check size={13} />}</span><div className="min-w-0 flex-1"><div className="flex justify-between text-sm"><span className="font-medium">{habit.name}</span><span className="text-xs text-zinc-400">{habit.count}/{habit.target} {habit.unit}</span></div><div className="mt-2"><Progress value={habit.progress} segments={habit.target} /></div></div><span className="relative shrink-0"><Flame size={16} className={habit.progress > 0 ? "text-orange-400" : "text-zinc-200"} />{streak > 0 && <span className="absolute -right-1.5 -top-1.5 grid h-3.5 w-3.5 place-items-center rounded-full bg-orange-500 text-[8px] font-bold leading-none text-white">{streak}</span>}</span></button>; })}{!habits.length && <p className="py-6 text-center text-sm text-zinc-400">Todavía no agregaste hábitos.</p>}</div><p className="mt-4 text-xs text-zinc-400">Un click suma una unidad. Doble click para editar.</p></Card>; }

function HabitsTracker({ habits }) {
  const [selectedId, setSelectedId] = useState(habits[0]?.id);
  const habit = habits.find((item) => item.id === selectedId) || habits[0];
  if (!habit) return null;
  const values = habit.history;
  const originX = 40, plotWidth = 260, baseline = 110;
  const stepX = values.length > 1 ? plotWidth / (values.length - 1) : 0;
  const pointX = (index) => originX + index * stepX;
  const points = values.map((value, index) => `${pointX(index)},${baseline - value}`).join(" ");
  const metric = habit.unit || "veces";
  return <Card><CardHeader eyebrow="Seguimiento" title="Tracker de hábitos" action={<Select label="" value={habit.id} onChange={setSelectedId} options={habits.map((item) => ({ value: item.id, label: item.name }))} />} /><svg viewBox="0 0 320 150" className="h-52 w-full" role="img" aria-label={`Tracker de ${habit.name}`}><text x="12" y="60" textAnchor="middle" transform="rotate(-90 12 60)" className="fill-zinc-400 text-[8px] uppercase tracking-wide">{metric}</text>{[0, 50, 100].map((tick) => <g key={tick}><text x={originX - 8} y={baseline - tick + 3} textAnchor="end" className="fill-zinc-400 text-[7px]">{tick}</text>{tick > 0 && tick < 100 && <line x1={originX} x2={originX + plotWidth} y1={baseline - tick} y2={baseline - tick} stroke="currentColor" strokeOpacity=".12" strokeDasharray="3 4" />}</g>)}<line x1={originX} x2={originX} y1="10" y2={baseline} stroke="currentColor" strokeOpacity=".25" /><line x1={originX} x2={originX + plotWidth} y1={baseline} y2={baseline} stroke="currentColor" strokeOpacity=".25" /><polyline points={points} fill="none" stroke="#84cc16" strokeWidth="4" strokeLinecap="round" strokeLinejoin="round" />{values.map((value, index) => { const previous = values[index - 1]; const trend = index === 0 ? "Punto inicial" : value > previous ? "Mejoraste" : value < previous ? "Empeoraste" : "Sin cambios"; return <circle key={index} cx={pointX(index)} cy={baseline - value} r="4" fill="#84cc16"><title>Día {index + 1}: {value} {metric} · {trend}</title></circle>; })}{values.map((value, index) => <text key={`d-${index}`} x={pointX(index)} y={baseline + 14} textAnchor="middle" className="fill-zinc-400 text-[7px]">{index + 1}</text>)}<text x={originX + plotWidth / 2} y="145" textAnchor="middle" className="fill-zinc-400 text-[8px] uppercase tracking-wide">Día</text></svg></Card>;
}

function Pomodoro({ settings, setSettings, seconds, setSeconds, running, setRunning, phase, setPhase, history }) { const time = `${String(Math.floor(seconds / 60)).padStart(2, "0")}:${String(seconds % 60).padStart(2, "0")}`; const totalSeconds = Math.max((phase === "work" ? settings.work : settings.breakTime) * 60, 1); const reset = () => { setRunning(false); setPhase("work"); setSeconds(settings.work * 60); }; const toggleRunning = () => { playClickSound(); setRunning(!running); }; const update = (key, value) => { const next = { ...settings, [key]: Number(value) }; setSettings(next); if (!running) { if (key === "work" && phase === "work") setSeconds(next.work * 60); if (key === "breakTime" && phase === "break") setSeconds(next.breakTime * 60); } }; return <div className="space-y-5"><Card className="text-center"><CardHeader eyebrow={phase === "work" ? "Sesión de foco" : "Descanso"} title="Pomodoro" action={<button onClick={reset} className="text-xs text-zinc-400">Reiniciar</button>} /><div className="mx-auto mt-4 grid h-56 w-56 place-items-center rounded-full" style={{ background: `conic-gradient(${phase === "work" ? "#a3e635" : "#7dd3fc"} ${seconds / totalSeconds * 100}%, #e4e4e7 0)` }}><div className="grid h-48 w-48 place-items-center rounded-full bg-white dark:bg-zinc-900"><p className="font-mono text-5xl font-semibold">{time}</p></div></div><button onClick={toggleRunning} className="mt-7 rounded-full bg-lime-300 px-7 py-3 text-sm font-semibold text-lime-950">{running ? "Pausar" : "Comenzar"}</button></Card><Card><CardHeader eyebrow="Personaliza tu foco" title="Configuración" action={<Settings2 size={17} className="text-zinc-400" />} /><div className="grid gap-3 sm:grid-cols-3">{[["repetitions", "Repeticiones"], ["work", "Temporizador (min)"], ["breakTime", "Descanso (min)"]].map(([key, label]) => <label key={key} className="text-xs text-zinc-500">{label}<input type="number" min="0" value={settings[key]} onChange={(event) => update(key, event.target.value)} className={`${inputClass} mt-1`} /></label>)}</div><p className="mt-5 text-sm font-semibold">Uso por día</p><div className="mt-3 flex h-24 items-end gap-2">{history.map((item) => <div key={item.day} className="group relative flex flex-1 flex-col items-center gap-1"><div className="w-full rounded-t bg-lime-400" style={{ height: `${Math.max(4, item.minutes / 125 * 80)}px` }} /><span className="text-[10px] text-zinc-400">{item.day}</span><span className="pointer-events-none absolute bottom-full mb-1 hidden rounded bg-zinc-900 px-2 py-1 text-[10px] text-white group-hover:block">{item.minutes} min</span></div>)}</div></Card></div>; }

function FinanceModal({ save, close }) { const [form, setForm] = useState({ description: "", amount: "", kind: "expense", category: "General" }); const update = (key, value) => setForm({ ...form, [key]: value }); return <Modal title="Nuevo movimiento" close={close}><div className="mt-5 space-y-3"><input autoFocus value={form.description} onChange={(event) => update("description", event.target.value)} placeholder="Descripción" className={inputClass} /><div className="grid grid-cols-2 gap-3"><label className="text-xs text-zinc-500">Monto<input type="number" min="0" value={form.amount} onChange={(event) => update("amount", event.target.value)} className={`${inputClass} mt-1`} /></label><Select label="Tipo" value={form.kind} onChange={(value) => update("kind", value)} options={[{ value: "expense", label: "Egreso" }, { value: "income", label: "Ingreso" }]} /></div><Select label="Categoría" value={form.category} onChange={(value) => update("category", value)} options={["General", "Alimentación", "Transporte", "Servicios", "Salario"]} /></div><button onClick={() => Number(form.amount) > 0 && form.description.trim() && save({ ...form, amount: Number(form.amount), description: form.description.trim(), id: Date.now() })} className="mt-6 w-full rounded-xl bg-zinc-900 py-3 text-sm font-semibold text-white">Guardar movimiento</button></Modal>; }

const EXPENSE_COLORS = ["#2a78d6", "#eb6834", "#1baf7a"];

function ExpensePie({ data }) {
  const total = data.reduce((sum, item) => sum + item.amount, 0);
  const radius = 40;
  const circumference = 2 * Math.PI * radius;
  const slices = data.reduce((acc, item) => { const length = total ? (item.amount / total) * circumference : 0; acc.list.push({ ...item, length, offset: acc.cumulative }); acc.cumulative += length; return acc; }, { list: [], cumulative: 0 }).list;
  return <div className="flex flex-col items-center gap-6 sm:flex-row sm:justify-center"><svg viewBox="0 0 100 100" className="h-44 w-44 shrink-0 -rotate-90"><circle cx="50" cy="50" r={radius} fill="none" strokeWidth="20" className="stroke-zinc-100 dark:stroke-zinc-800" />{slices.map((slice, index) => <circle key={slice.category} cx="50" cy="50" r={radius} fill="none" strokeWidth="20" stroke={slice.color} strokeDasharray={`${slice.length} ${circumference - slice.length}`} className="pie-slice" style={{ "--pie-from": -(slice.offset + slice.length), "--pie-to": -slice.offset, animationDelay: `${index * 120}ms` }} />)}</svg><ul className="w-full max-w-xs space-y-2 text-sm">{slices.map((slice) => <li key={slice.category} className="flex items-center gap-2"><i className="h-2.5 w-2.5 shrink-0 rounded-full" style={{ backgroundColor: slice.color }} /><span className="flex-1 truncate">{slice.category}</span><span className="text-xs text-zinc-400">{total ? Math.round((slice.amount / total) * 100) : 0}%</span><strong className="w-20 text-right">$ {slice.amount.toLocaleString("es-AR")}</strong></li>)}</ul></div>;
}

function parseRowDate(value) { const [day, month, year] = value.split("/").map(Number); return new Date(year, month - 1, day).getTime(); }

const ROW_SORTERS = {
  date: (row) => parseRowDate(row.date),
  type: (row) => row.type,
  amount: (row) => row.amount,
  description: (row) => row.description.toLowerCase(),
  category: (row) => row.category.toLowerCase(),
};

const PAGE_SIZE = 20;

function SortableHead({ label, columnKey, sortKey, sortDir, onSort }) {
  const active = sortKey === columnKey;
  return <TableHead><button type="button" onClick={() => onSort(columnKey)} className="flex items-center gap-1 hover:text-zinc-700 dark:hover:text-zinc-200">{label}{active ? sortDir === "asc" ? <ArrowUp size={12} /> : <ArrowDown size={12} /> : <ArrowUpDown size={12} className="opacity-40" />}</button></TableHead>;
}

const MONTH_NAMES = ["Enero", "Febrero", "Marzo", "Abril", "Mayo", "Junio", "Julio", "Agosto", "Septiembre", "Octubre", "Noviembre", "Diciembre"];
const monthLabel = (iso) => { const d = new Date(iso); return `${MONTH_NAMES[d.getMonth()]} ${d.getFullYear()}`; };
const monthSortValue = (iso) => { const d = new Date(iso); return d.getFullYear() * 12 + d.getMonth(); };
const formatRowDate = (iso) => { const d = new Date(iso); return `${String(d.getDate()).padStart(2, "0")}/${String(d.getMonth() + 1).padStart(2, "0")}/${d.getFullYear()}`; };

function FinanceArchive({ transactions, openFinance, onDelete }) {
  const rows = transactions.map((tx) => ({ id: tx.id, date: formatRowDate(tx.createdAt), month: monthLabel(tx.createdAt), sortValue: monthSortValue(tx.createdAt), type: tx.kind === "income" ? "Ingreso" : "Egreso", amount: tx.amount, description: tx.description, category: tx.category }));
  const nowIso = new Date().toISOString();
  const monthOptions = new Map([[monthLabel(nowIso), monthSortValue(nowIso)]]);
  rows.forEach((row) => { if (!monthOptions.has(row.month)) monthOptions.set(row.month, row.sortValue); });
  const months = [...monthOptions.entries()].sort((a, b) => b[1] - a[1]).map(([label]) => label);
  const [month, setMonth] = useState(monthLabel(nowIso));
  const [search, setSearch] = useState(""); const [sortKey, setSortKey] = useState("date"); const [sortDir, setSortDir] = useState("desc"); const [page, setPage] = useState(1);
  const monthRows = rows.filter((row) => row.month === month);
  const balance = monthRows.reduce((sum, row) => sum + (row.type === "Ingreso" ? row.amount : -row.amount), 0); const expenseTotals = {}; monthRows.forEach((row) => { if (row.type === "Egreso") expenseTotals[row.category] = (expenseTotals[row.category] || 0) + row.amount; }); const sortedExpenses = Object.entries(expenseTotals).map(([category, amount]) => ({ category, amount })).sort((a, b) => b.amount - a.amount); const topExpenses = sortedExpenses.slice(0, 3).map((item, index) => ({ ...item, color: EXPENSE_COLORS[index] })); const otherExpenses = sortedExpenses.slice(3).reduce((sum, item) => sum + item.amount, 0); const expenseData = otherExpenses > 0 ? [...topExpenses, { category: "Otros", amount: otherExpenses, color: "#a1a1aa" }] : topExpenses;
  const changeMonth = (value) => { setMonth(value); setPage(1); };
  const updateSearch = (value) => { setSearch(value); setPage(1); };
  const toggleSort = (key) => { if (sortKey === key) setSortDir(sortDir === "asc" ? "desc" : "asc"); else { setSortKey(key); setSortDir("asc"); } setPage(1); };
  const searchTerm = search.trim().toLowerCase();
  const filteredRows = monthRows.filter((row) => [row.date, row.type, row.amount.toLocaleString("es-AR"), row.description, row.category].join(" ").toLowerCase().includes(searchTerm));
  const sortedRows = [...filteredRows].sort((a, b) => { const valueA = ROW_SORTERS[sortKey](a); const valueB = ROW_SORTERS[sortKey](b); const compare = valueA < valueB ? -1 : valueA > valueB ? 1 : 0; return sortDir === "asc" ? compare : -compare; });
  const totalPages = Math.max(1, Math.ceil(sortedRows.length / PAGE_SIZE));
  const currentPage = Math.min(page, totalPages);
  const pageRows = sortedRows.slice((currentPage - 1) * PAGE_SIZE, currentPage * PAGE_SIZE);
  return <div className="space-y-5"><Card><CardHeader eyebrow="Archivo financiero" title="Balance mensual" action={<div className="flex items-center gap-2"><Select label="" value={month} onChange={changeMonth} options={months} /><button onClick={openFinance} className="flex items-center gap-1 rounded-lg bg-zinc-900 px-3 py-2 text-xs font-medium text-white"><Plus size={14} /> Movimiento</button></div>} /><p className="text-4xl font-semibold">$ {balance.toLocaleString("es-AR", { minimumFractionDigits: 2 })}</p><p className="mt-2 text-sm text-zinc-500">{month} · Ingresos menos egresos</p></Card><Card><CardHeader eyebrow="Distribución" title="Gastos por categoría" />{expenseData.length ? <ExpensePie key={month} data={expenseData} /> : <p className="py-8 text-center text-sm text-zinc-400">No hay egresos registrados este mes.</p>}</Card><Card><CardHeader eyebrow="Detalle" title="Movimientos del mes" action={<Input value={search} onChange={(event) => updateSearch(event.target.value)} placeholder="Buscar movimiento..." className="w-48" />} /><Table><TableHeader><TableRow><SortableHead label="Fecha" columnKey="date" sortKey={sortKey} sortDir={sortDir} onSort={toggleSort} /><SortableHead label="Tipo" columnKey="type" sortKey={sortKey} sortDir={sortDir} onSort={toggleSort} /><SortableHead label="Monto" columnKey="amount" sortKey={sortKey} sortDir={sortDir} onSort={toggleSort} /><SortableHead label="Descripción" columnKey="description" sortKey={sortKey} sortDir={sortDir} onSort={toggleSort} /><SortableHead label="Categoría" columnKey="category" sortKey={sortKey} sortDir={sortDir} onSort={toggleSort} /><TableHead /></TableRow></TableHeader><TableBody>{pageRows.length ? pageRows.map((row) => <TableRow key={row.id}><TableCell className="text-zinc-500">{row.date}</TableCell><TableCell className={row.type === "Ingreso" ? "text-lime-600" : "text-red-500"}>{row.type}</TableCell><TableCell className="font-medium">$ {row.amount.toLocaleString("es-AR")}</TableCell><TableCell>{row.description}</TableCell><TableCell className="text-zinc-500">{row.category}</TableCell><TableCell><button type="button" onClick={() => onDelete(row.id)} aria-label="Eliminar movimiento" className="text-zinc-400 hover:text-red-500"><Trash2 size={14} /></button></TableCell></TableRow>) : <TableRow><TableCell colSpan={6} className="py-8 text-center text-zinc-400">No se encontraron movimientos.</TableCell></TableRow>}</TableBody></Table><div className="mt-5 flex flex-wrap items-center justify-between gap-3"><span className="text-xs text-zinc-400">{sortedRows.length ? `${(currentPage - 1) * PAGE_SIZE + 1}–${Math.min(currentPage * PAGE_SIZE, sortedRows.length)} de ${sortedRows.length}` : "0 resultados"}</span><Pagination page={currentPage} totalPages={totalPages} onChange={setPage} /></div></Card></div>; }

function DraggableCard({ id, onReorder, children }) {
  const [dragging, setDragging] = useState(false);
  const [dragOver, setDragOver] = useState(false);
  const onDragStart = (event) => { event.dataTransfer.effectAllowed = "move"; event.dataTransfer.setData("text/plain", id); setDragging(true); };
  const onDragEnd = () => setDragging(false);
  const onDragOver = (event) => { event.preventDefault(); event.stopPropagation(); if (!dragOver) setDragOver(true); };
  const onDragLeave = () => setDragOver(false);
  const onDrop = (event) => { event.preventDefault(); event.stopPropagation(); setDragOver(false); const draggedId = event.dataTransfer.getData("text/plain"); if (draggedId && draggedId !== id) onReorder(draggedId, id); };
  return <div className={`relative rounded-2xl transition-[opacity,box-shadow] duration-150 ${dragging ? "opacity-40" : ""} ${dragOver ? "ring-2 ring-lime-400 ring-offset-2 ring-offset-[#f4f5ef] dark:ring-offset-zinc-950" : ""}`} onDragOver={onDragOver} onDragLeave={onDragLeave} onDrop={onDrop}>{children}<button type="button" draggable onDragStart={onDragStart} onDragEnd={onDragEnd} aria-label="Arrastrar para reordenar" title="Arrastrar para reordenar" className="absolute -right-2 -top-2 grid h-7 w-7 cursor-grab place-items-center rounded-full border border-zinc-200 bg-white text-zinc-400 shadow-sm hover:text-zinc-600 active:cursor-grabbing dark:border-zinc-700 dark:bg-zinc-900 dark:hover:text-zinc-300"><MoreVertical size={14} /></button></div>;
}

function ColumnDropZone({ columnIndex, onDropToColumn }) {
  const [dragOver, setDragOver] = useState(false);
  const onDragOver = (event) => { event.preventDefault(); if (!dragOver) setDragOver(true); };
  const onDragLeave = () => setDragOver(false);
  const onDrop = (event) => { event.preventDefault(); setDragOver(false); const draggedId = event.dataTransfer.getData("text/plain"); if (draggedId) onDropToColumn(draggedId, columnIndex); };
  return <div onDragOver={onDragOver} onDragLeave={onDragLeave} onDrop={onDrop} className={`grid min-h-10 place-items-center rounded-2xl border-2 border-dashed transition-colors ${dragOver ? "border-lime-400 bg-lime-100/40 dark:bg-lime-500/10" : "border-transparent"}`}>{dragOver && <span className="text-xs font-medium text-lime-600">Soltar al final de esta columna</span>}</div>;
}

function SummaryColumn({ columnIndex, ids, widgets, onReorder, onDropToColumn }) {
  return <div className="flex flex-1 flex-col gap-5">{ids.map((id) => <DraggableCard key={id} id={id} onReorder={onReorder}>{widgets[id]}</DraggableCard>)}<ColumnDropZone columnIndex={columnIndex} onDropToColumn={onDropToColumn} /></div>;
}

function UnifiedAgenda({ tasks, events, date, toggle, toggleEvent, openTask, openEvent }) { const items = [...tasks.filter((task) => task.date === date).map((task) => ({ ...task, itemType: "Tarea" })), ...events.filter((event) => event.date === date).map((event) => ({ ...event, itemType: "Evento" }))].sort((a, b) => a.time.localeCompare(b.time)); return <Card><CardHeader eyebrow={`Agenda del ${date}`} title="Tareas y eventos" action={<div className="flex gap-3"><button onClick={() => openTask(null, date)} className="flex items-center gap-1 text-sm font-semibold text-lime-700"><Plus size={15} /> Tarea</button><button onClick={() => openEvent(null, date)} className="flex items-center gap-1 text-sm font-semibold text-lime-700"><Plus size={15} /> Evento</button></div>} />{items.length ? <div className="space-y-2">{items.map((item) => item.itemType === "Evento" ? <button key={`event-${item.id}`} onClick={() => toggleEvent(item.id)} onDoubleClick={() => openEvent(item, date)} className="flex w-full items-center gap-3 rounded-xl p-3 text-left transition-colors hover:brightness-95" style={{ backgroundColor: `${item.color}55` }}><span className={`grid h-5 w-5 shrink-0 place-items-center rounded-md border transition-transform duration-300 ${item.done ? "scale-95 border-zinc-700 bg-zinc-700 text-white" : "border-zinc-400"}`}>{item.done && <Check size={13} />}</span><span className="h-8 w-1 rounded-full" style={{ backgroundColor: item.color }} /><span className="w-12 text-xs text-zinc-500">{item.time}</span><span className={`flex-1 text-sm font-medium ${item.done ? "text-zinc-500" : ""}`}><span className={item.done ? "task-strike" : ""}>{item.title}</span></span><span className="text-xs text-zinc-500">{item.type}</span></button> : <button key={`task-${item.id}`} onClick={() => toggle(item.id)} onDoubleClick={() => openTask(item, date)} className="flex w-full items-center gap-3 rounded-xl p-3 text-left hover:bg-zinc-50 dark:hover:bg-zinc-800"><span className={`grid h-5 w-5 shrink-0 place-items-center rounded-full border ${item.done ? "border-lime-500 bg-lime-400" : "border-zinc-300"}`}>{item.done && <Check size={13} />}</span><span className="w-12 text-xs text-zinc-400">{item.time}</span><span className={`flex-1 text-sm ${item.done ? "text-zinc-400" : ""}`}><span className={item.done ? "task-strike" : ""}>{item.title}</span></span><span className="text-xs text-zinc-500">{item.category}</span></button>)}</div> : <p className="py-8 text-center text-sm text-zinc-400">No hay tareas ni eventos para este día.</p>}</Card>; }

export default function Page() {
  return <AuthGate>{(user, logout) => <Home user={user} logout={logout} />}</AuthGate>;
}

function Home({ user, logout }) {
  const [active, setActive] = useState("resumen"); const [dark, setDark] = useState(false); const [wave, setWave] = useState(false); const [tasks, setTasks] = useState([]); const [habits, setHabits] = useState([]); const [transactions, setTransactions] = useState([]); const [events, setEvents] = useState([]); const [date, setDate] = useState(today); const [taskModal, setTaskModal] = useState(null); const [habitModal, setHabitModal] = useState(null); const [dayModal, setDayModal] = useState(null); const [eventModal, setEventModal] = useState(null); const [financeOpen, setFinanceOpen] = useState(false); const [seconds, setSeconds] = useState(0); const [running, setRunning] = useState(false); const [phase, setPhase] = useState("work"); const [settings, setSettingsState] = useState({ repetitions: 0, work: 0, breakTime: 0 }); const [summaryColumns, setSummaryColumns] = useState([["hero", "pomodoro"], ["calendar", "agenda", "habits"]]); const [hoursPeriod, setHoursPeriod] = useState(null); const [hourEntries, setHourEntries] = useState([]); const [hourPayments, setHourPayments] = useState([]); const [closedPeriods, setClosedPeriods] = useState([]); const [pomodoroHistory, setPomodoroHistory] = useState([]); const [loading, setLoading] = useState(true); const weekdayLetters = ["D", "L", "M", "X", "J", "V", "S"]; const pomodoroChartData = pomodoroHistory.map((entry) => ({ day: weekdayLetters[new Date(`${entry.date}T12:00:00`).getDay()], minutes: entry.minutes }));
  const settingsRef = useRef(settings); useEffect(() => { settingsRef.current = settings; }, [settings]);
  const phaseRef = useRef(phase); useEffect(() => { phaseRef.current = phase; }, [phase]);
  const workSecondsRef = useRef(0);
  const logPomodoroMinute = () => { const todayStr = new Date().toISOString().slice(0, 10); setPomodoroHistory((current) => current.map((entry) => entry.date === todayStr ? { ...entry, minutes: entry.minutes + 1 } : entry)); api("/pomodoro/log", { method: "POST", body: JSON.stringify({ minutes: 1 }) }).catch(() => {}); };
  useEffect(() => { if (!running) return undefined; const timer = setInterval(() => { setSeconds((value) => { if (value > 0) return value - 1; playAlarmSound(); const nextPhase = phaseRef.current === "work" ? "break" : "work"; setPhase(nextPhase); return (nextPhase === "work" ? settingsRef.current.work : settingsRef.current.breakTime) * 60; }); if (phaseRef.current === "work") { workSecondsRef.current += 1; if (workSecondsRef.current >= 60) { workSecondsRef.current -= 60; logPomodoroMinute(); } } }, 1000); return () => clearInterval(timer); }, [running]);
  const applyHoursState = (data) => { setHoursPeriod(data.period); setHourEntries(data.entries.map(fromApiEntry)); setHourPayments(data.payments.map(fromApiPayment)); setClosedPeriods(data.closed_periods.map(fromApiClosedPeriod)); };
  useEffect(() => { Promise.all([api("/dashboard"), api("/events"), api("/pomodoro"), api("/hours"), api("/pomodoro/history")]).then(([dashboardData, eventsData, pomodoroData, hoursData, historyData]) => { setTasks(dashboardData.tasks.map(fromApiTask)); setHabits(dashboardData.habits.map(fromApiHabit)); setTransactions(dashboardData.transactions.map(fromApiTransaction)); setEvents(eventsData.map(fromApiEvent)); setSettingsState(fromApiSettings(pomodoroData)); applyHoursState(hoursData); setPomodoroHistory(historyData); setLoading(false); }).catch(() => logout()); }, [logout]);
  const quote = useMemo(() => quotes[new Date().getDate() % quotes.length], []);
  if (loading) return <div className="grid min-h-screen place-items-center bg-[#f4f5ef] dark:bg-zinc-950"><p className="text-sm text-zinc-400">Cargando tu día…</p></div>;
  const hour = new Date().getHours(); const greeting = hour < 12 ? "Buen día" : hour < 19 ? "Buenas tardes" : "Buenas noches";
  const setSettings = (next) => { setSettingsState(next); api("/pomodoro", { method: "PATCH", body: JSON.stringify(toApiSettings(next)) }).catch(() => {}); };
  const saveHourEntry = (form) => { const previous = hourEntries; const existing = hourEntries.find((entry) => entry.date === form.date); setHourEntries(existing ? hourEntries.map((entry) => entry.date === form.date ? { ...form, id: existing.id } : entry) : [...hourEntries, { ...form, id: `temp-${form.date}` }]); api("/hours/entries", { method: "PUT", body: JSON.stringify(toApiEntry(form)) }).then((saved) => setHourEntries((current) => current.map((entry) => entry.date === form.date ? fromApiEntry(saved) : entry))).catch(() => setHourEntries(previous)); };
  const removeHourEntry = (id) => { const previous = hourEntries; setHourEntries(hourEntries.filter((entry) => entry.id !== id)); api(`/hours/entries/${id}`, { method: "DELETE" }).catch(() => setHourEntries(previous)); };
  const toggleTask = (id) => { setTasks(tasks.map((task) => task.id === id ? { ...task, done: !task.done } : task)); api(`/tasks/${id}/complete`, { method: "PATCH" }).catch(() => setTasks((current) => current.map((task) => task.id === id ? { ...task, done: !task.done } : task))); };
  const openTask = (task, selectedDate = date) => { setDate(selectedDate); setTaskModal(task || { date: selectedDate }); };
  const saveTask = (task) => { const existing = tasks.find((item) => item.id === task.id); const payload = toApiTask(task); setTasks(existing ? tasks.map((item) => item.id === task.id ? task : item) : [...tasks, task]); setTaskModal(null); if (existing) { api(`/tasks/${task.id}`, { method: "PATCH", body: JSON.stringify(payload) }).then((updated) => setTasks((current) => current.map((item) => item.id === task.id ? fromApiTask(updated) : item))).catch(() => setTasks((current) => current.map((item) => item.id === task.id ? existing : item))); } else { api("/tasks", { method: "POST", body: JSON.stringify(payload) }).then((created) => setTasks((current) => current.map((item) => item.id === task.id ? fromApiTask(created) : item))).catch(() => setTasks((current) => current.filter((item) => item.id !== task.id))); } };
  const deleteTask = (id) => { const previous = tasks; setTasks(tasks.filter((task) => task.id !== id)); setTaskModal(null); api(`/tasks/${id}`, { method: "DELETE" }).catch(() => setTasks(previous)); };
  const toggleHabit = (id) => { const habit = habits.find((item) => item.id === id); if (!habit) return; const nextCount = habit.count >= habit.target ? 0 : habit.count + 1; const progress = Math.round(nextCount / habit.target * 100); setHabits(habits.map((item) => item.id === id ? { ...item, count: nextCount, progress } : item)); api(`/habits/${id}/increment`, { method: "PATCH" }).then((updated) => setHabits((current) => current.map((item) => item.id === id ? fromApiHabit(updated) : item))).catch(() => setHabits((current) => current.map((item) => item.id === id ? habit : item))); };
  const saveHabit = (habit) => { const existing = habits.find((item) => item.id === habit.id); setHabits(existing ? habits.map((item) => item.id === habit.id ? habit : item) : [...habits, habit]); setHabitModal(null); if (existing) { api(`/habits/${habit.id}`, { method: "PATCH", body: JSON.stringify({ name: habit.name, target: habit.target, unit: habit.unit }) }).then((updated) => setHabits((current) => current.map((item) => item.id === habit.id ? fromApiHabit(updated) : item))).catch(() => setHabits((current) => current.map((item) => item.id === habit.id ? existing : item))); } else { api("/habits", { method: "POST", body: JSON.stringify({ name: habit.name, target: habit.target, unit: habit.unit }) }).then((created) => setHabits((current) => current.map((item) => item.id === habit.id ? fromApiHabit(created) : item))).catch(() => setHabits((current) => current.filter((item) => item.id !== habit.id))); } };
  const deleteHabit = (id) => { const previous = habits; setHabits(habits.filter((habit) => habit.id !== id)); setHabitModal(null); api(`/habits/${id}`, { method: "DELETE" }).catch(() => setHabits(previous)); };
  const addTransaction = (item) => { const tempId = Date.now(); setTransactions([...transactions, { id: tempId, description: item.description, amount: item.amount, kind: item.kind, category: item.category, createdAt: new Date().toISOString() }]); setFinanceOpen(false); api("/transactions", { method: "POST", body: JSON.stringify({ description: item.description, amount: item.amount, kind: item.kind, category: item.category }) }).then((created) => setTransactions((current) => current.map((entry) => entry.id === tempId ? fromApiTransaction(created) : entry))).catch(() => setTransactions((current) => current.filter((entry) => entry.id !== tempId))); };
  const deleteTransaction = (id) => { const previous = transactions; setTransactions(transactions.filter((item) => item.id !== id)); api(`/transactions/${id}`, { method: "DELETE" }).catch(() => setTransactions(previous)); };
  const shared = { tasks, date, setDate, toggle: toggleTask, openTask }; const toggleEvent = (id) => { const previous = events.find((item) => item.id === id); setEvents(events.map((event) => event.id === id ? { ...event, done: !event.done } : event)); api(`/events/${id}/toggle`, { method: "PATCH" }).catch(() => setEvents((current) => current.map((event) => event.id === id ? previous : event))); }; const openEvent = (event, selectedDate = date) => { setDate(selectedDate); setEventModal(event || { date: selectedDate }); }; const saveEvent = (event) => { const existing = events.find((item) => item.id === event.id); const payload = toApiEvent(event); setEvents(existing ? events.map((item) => item.id === event.id ? event : item) : [...events, { ...event, done: false }]); setEventModal(null); if (existing) { api(`/events/${event.id}`, { method: "PATCH", body: JSON.stringify(payload) }).then((updated) => setEvents((current) => current.map((item) => item.id === event.id ? fromApiEvent(updated) : item))).catch(() => setEvents((current) => current.map((item) => item.id === event.id ? existing : item))); } else { api("/events", { method: "POST", body: JSON.stringify(payload) }).then((created) => setEvents((current) => current.map((item) => item.id === event.id ? fromApiEvent(created) : item))).catch(() => setEvents((current) => current.filter((item) => item.id !== event.id))); } }; const deleteEvent = (id) => { const previous = events; setEvents(events.filter((event) => event.id !== id)); setEventModal(null); api(`/events/${id}`, { method: "DELETE" }).catch(() => setEvents(previous)); }; const reorderSummary = (draggedId, targetId) => setSummaryColumns((current) => { const next = current.map((column) => column.filter((item) => item !== draggedId)); const targetColumnIndex = next.findIndex((column) => column.includes(targetId)); if (targetColumnIndex === -1) return current; const targetColumn = [...next[targetColumnIndex]]; targetColumn.splice(targetColumn.indexOf(targetId), 0, draggedId); next[targetColumnIndex] = targetColumn; return next; }); const moveSummaryToColumn = (draggedId, columnIndex) => setSummaryColumns((current) => { const next = current.map((column) => column.filter((item) => item !== draggedId)); next[columnIndex] = [...next[columnIndex], draggedId]; return next; });
  const summaryWidgets = { hero: <Card className="bg-zinc-200 dark:bg-zinc-800"><CardHeader eyebrow="Tu día" title="En camino" /><p className="text-4xl font-semibold leading-tight">Pequeños pasos,<br /><span className="text-lime-600">gran progreso.</span></p><p className="mt-6 border-l-2 border-lime-500 pl-3 text-sm italic text-zinc-700 dark:text-zinc-200">“{quote.text}”<span className="mt-2 block text-xs not-italic text-lime-700 dark:text-lime-300">— {quote.author}</span></p><Progress value={tasks.length ? tasks.filter((task) => task.done).length / tasks.length * 100 : 0} color="bg-lime-500" /></Card>, pomodoro: <Pomodoro settings={settings} setSettings={setSettings} seconds={seconds} setSeconds={setSeconds} running={running} setRunning={setRunning} phase={phase} setPhase={setPhase} history={pomodoroChartData} />, calendar: <Card><CardHeader eyebrow="Calendario" title="Tu agenda" /><Calendar value={date} onChange={setDate} onDoubleClick={setDayModal} markers={events.map((event) => ({ date: event.date, color: event.color }))} /></Card>, agenda: <UnifiedAgenda tasks={tasks} events={events} date={date} toggle={toggleTask} toggleEvent={toggleEvent} openTask={openTask} openEvent={openEvent} />, habits: <Habits habits={habits} onToggle={toggleHabit} openHabit={setHabitModal} /> };
  const content = active === "tareas" ? <TaskList {...shared} /> : active === "pomodoro" ? <Pomodoro settings={settings} setSettings={setSettings} seconds={seconds} setSeconds={setSeconds} running={running} setRunning={setRunning} phase={phase} setPhase={setPhase} history={pomodoroChartData} /> : active === "hábitos" ? <div className="space-y-5"><Habits habits={habits} onToggle={toggleHabit} openHabit={setHabitModal} /><HabitsTracker habits={habits} /></div> : active === "calendario" ? <Card><CardHeader eyebrow="Agenda" title="Calendario" /><Calendar value={date} onChange={setDate} onDoubleClick={setDayModal} markers={events.map((event) => ({ date: event.date, color: event.color }))} /><div className="mt-5"><UnifiedAgenda tasks={tasks} events={events} date={date} toggle={toggleTask} toggleEvent={toggleEvent} openTask={openTask} openEvent={openEvent} /></div></Card> : active === "horas" ? <HoursPanel period={hoursPeriod} setPeriod={setHoursPeriod} entries={hourEntries} setEntries={setHourEntries} payments={hourPayments} setPayments={setHourPayments} closedPeriods={closedPeriods} setClosedPeriods={setClosedPeriods} onSaveEntry={saveHourEntry} onRemoveEntry={removeHourEntry} /> : active === "finanzas" ? <FinanceArchive transactions={transactions} openFinance={() => setFinanceOpen(true)} onDelete={deleteTransaction} /> : <div className="flex flex-col gap-5 xl:flex-row xl:items-start">{summaryColumns.map((ids, columnIndex) => <SummaryColumn key={columnIndex} columnIndex={columnIndex} ids={ids} widgets={summaryWidgets} onReorder={reorderSummary} onDropToColumn={moveSummaryToColumn} />)}</div>;
  return <main className={dark ? "dark" : ""}>{wave && <div className={`theme-wave ${dark ? "theme-wave-dark" : "theme-wave-light"}`} />}<div className="min-h-screen bg-[#f4f5ef] text-zinc-900 transition-colors duration-300 dark:bg-zinc-950 dark:text-zinc-100"><div className="mx-auto flex min-h-screen max-w-[1500px]"><aside className="app-sidebar hidden w-64 shrink-0 flex-col border-r border-zinc-200/80 bg-[#fbfcf7] p-7 dark:border-zinc-800 dark:bg-zinc-900 lg:flex"><div className="flex items-center gap-3"><Image src="/logo.png" alt="Dayflow" width={40} height={40} className="h-10 w-10 rounded-xl" /><span className="text-xl font-semibold">dayflow</span></div><nav className="mt-16 space-y-2 text-sm font-medium">{tabs.map(([id, label, Icon]) => <button key={id} onClick={() => setActive(id)} className={`flex w-full items-center gap-3 rounded-xl px-4 py-3 text-left ${active === id ? "bg-zinc-900 text-white" : "text-zinc-500 hover:bg-zinc-100 dark:hover:bg-zinc-800"}`}><Icon size={18} />{label}</button>)}</nav></aside><section className="w-full px-5 py-7 sm:px-8 lg:px-12"><header className="app-header flex items-start justify-between"><div><p className="text-sm font-medium text-zinc-400">Martes, 24 de agosto de 2026</p><h1 className="mt-2 text-3xl font-semibold sm:text-4xl">{greeting}, {user.full_name.split(" ")[0]} <span className="text-lime-600">✦</span></h1></div><div className="flex items-center gap-2"><button onClick={() => { setWave(true); setDark(!dark); window.setTimeout(() => setWave(false), 500); }} aria-label="Cambiar tema" className="grid h-10 w-10 place-items-center rounded-full border border-zinc-200 bg-white shadow-sm dark:border-zinc-800 dark:bg-zinc-900">{dark ? <Sun size={17} /> : <Moon size={17} />}</button><button onClick={logout} aria-label="Cerrar sesión" title="Cerrar sesión" className="grid h-10 w-10 place-items-center rounded-full border border-zinc-200 bg-white shadow-sm dark:border-zinc-800 dark:bg-zinc-900"><LogOut size={17} /></button></div></header><div className="mt-8 flex gap-2 overflow-x-auto pb-1 lg:hidden">{tabs.map(([id, label, Icon]) => <button key={id} onClick={() => setActive(id)} className={`flex shrink-0 items-center gap-2 rounded-full px-3 py-2 text-xs font-medium ${active === id ? "bg-zinc-900 text-white" : "bg-white text-zinc-500 dark:bg-zinc-900"}`}><Icon size={14} />{label}</button>)}</div><div key={active} className="tab-panel mt-7">{content}</div></section></div></div>{taskModal && <TaskModal task={taskModal.id ? taskModal : null} date={taskModal.date || date} close={() => setTaskModal(null)} save={saveTask} remove={deleteTask} />}{habitModal && <HabitModal habit={habitModal} close={() => setHabitModal(null)} save={saveHabit} remove={deleteHabit} />}{financeOpen && <FinanceModal close={() => setFinanceOpen(false)} save={addTransaction} />}{eventModal && <EventModal event={eventModal.id ? eventModal : null} date={eventModal.date || date} close={() => setEventModal(null)} save={saveEvent} remove={deleteEvent} />}{dayModal && <DayModal date={dayModal} tasks={tasks} events={events} openTask={openTask} openEvent={openEvent} close={() => setDayModal(null)} />}</main>;
}




















